// Types for the StayOS demo dataset. JSON in this folder is generated by scripts/generate-data.mjs.

export type BlockId = "A" | "B" | "C";
export type Gender = "M" | "F";
export type RoomType = "single" | "double" | "triple" | "six";
export type BedStatus = "occupied" | "vacant" | "reserved" | "maintenance";
export type Meal = "breakfast" | "lunch" | "snacks" | "dinner";
export type LunchSpot = "institute" | "hostel";
export type ISODate = string; // 2026-11-27
export type ISODateTime = string; // 2026-11-27T10:24:00+05:30

export interface Block {
  id: BlockId;
  name: string;
  gender: Gender;
  floors: number;
  wardenId: string;
  curfew: string;
}

export interface Hostel {
  id: string;
  name: string;
  city: string;
  address: string;
  phone: string;
  whatsapp: string;
  upiId: string;
  bank: string;
  owner: { name: string; phone: string };
  wardenId: string;
  blocks: Block[];
  rentByType: Record<RoomType, number>;
  messFee: number;
  deposit: number;
  dueDay: number;
  now: ISODateTime;
  today: ISODate;
  months: string[];
}

export interface Room {
  id: string; // A-207
  block: BlockId;
  floor: number;
  number: string;
  type: RoomType;
  rent: number;
  capacity: number;
  bath: "attached" | "common";
}

export interface Bed {
  id: string; // A-207-2
  roomId: string;
  block: BlockId;
  floor: number;
  label: string;
  status: BedStatus;
  residentId?: string;
  reservation?: { name: string; from: ISODate; advance: number; phone: string };
  maintenanceNote?: string;
}

export interface Resident {
  id: string;
  name: string;
  gender: Gender;
  phone: string;
  dob: ISODate;
  bloodGroup: string;
  hometown: string;
  occupation: "student" | "professional";
  institution: string;
  parent: { name: string; relation: "Father" | "Mother" | "Guardian"; phone: string };
  bedId: string;
  checkInDate: ISODate;
  checkOutDate: ISODate | null;
  status: "active" | "notice" | "checked_out";
  kyc: { status: "verified" | "pending" | "manual"; method: "digilocker" | "offline"; aadhaarLast4: string; verifiedOn: ISODate | null };
  police: { status: "approved" | "submitted" | "pending"; refNo: string | null; submittedOn: ISODate | null };
  messPlan: boolean;
  deposit: number;
}

export type InvoiceLineKind = "rent" | "mess" | "rebate" | "deposit";
export interface Invoice {
  id: string;
  residentId: string;
  month: string; // 2026-11
  issuedOn: ISODate;
  dueOn: ISODate;
  lines: { kind: InvoiceLineKind; label: string; amount: number }[];
  total: number;
  status: "paid" | "unpaid";
  paidOn: ISODateTime | null;
  method: "upi" | "bank" | "cash" | null;
  utr: string | null;
  paidVia: "whatsapp_link" | "app" | "qr" | null;
  remindersSent: number;
}

export type ExpenseCategory = "food" | "electricity" | "water" | "salaries" | "maintenance" | "internet";
export interface Expense {
  id: string;
  date: ISODate;
  category: ExpenseCategory;
  vendor: string;
  description: string;
  amount: number;
  mode: "bank" | "upi" | "cash";
  receipt: { fileName: string; pages: number; dataUrl?: string } | null;
  status: "paid" | "scheduled";
}

export type AttendanceMark = "P" | "A" | "L" | "H" | "late";
export interface Staff {
  id: string;
  name: string;
  role: "warden" | "office" | "cook" | "cleaner" | "security" | "maintenance";
  title: string;
  salary: number;
  shift: string;
  phone: string;
  joinedOn: ISODate;
  attendance: Record<ISODate, AttendanceMark>;
  advance: number;
}

export type ComplaintCategory = "electrical" | "plumbing" | "wifi" | "housekeeping" | "mess" | "furniture" | "other";
export type ComplaintStatus = "new" | "in_progress" | "resolved";
export type Channel = "whatsapp" | "app" | "walk_in";
export interface ComplaintUpdate {
  at: ISODateTime;
  kind: "created" | "assigned" | "on_the_way" | "resolved" | "note";
  by: string;
  note?: string;
}
export interface Complaint {
  id: string;
  residentId: string;
  roomId: string;
  category: ComplaintCategory;
  title: string;
  description: string;
  channel: Channel;
  status: ComplaintStatus;
  priority: "low" | "medium" | "high";
  createdAt: ISODateTime;
  slaHours: number;
  assignedTo: string | null;
  resolvedAt: ISODateTime | null;
  rating: number | null;
  updates: ComplaintUpdate[];
  photo?: string; // svg scene key or data URL
}

export interface GateEvent {
  id: string;
  residentId: string;
  type: "in" | "out";
  at: ISODateTime;
  method: "qr" | "manual";
  late: boolean;
  passId: string | null;
}

export interface LeaveRequest {
  id: string;
  residentId: string;
  from: ISODateTime;
  to: ISODateTime;
  reason: string;
  destination: string;
  status: "awaiting_parent" | "approved" | "rejected" | "cancelled";
  requestedAt: ISODateTime;
  parentDecisionAt: ISODateTime | null;
}

export interface Visitor {
  id: string;
  name: string;
  phone: string;
  relation: string;
  residentId: string;
  purpose: string;
  inAt: ISODateTime;
  outAt: ISODateTime | null;
  idProof: string;
  idLast4: string;
}

export interface MenuItem {
  en: string;
  ml: string;
  veg: boolean;
}
export interface MenuDay {
  day: number; // 0 = Sunday
  breakfast: MenuItem;
  lunch: MenuItem;
  snacks: MenuItem;
  dinner: MenuItem;
  special?: MenuItem;
}
export interface MealOptOut {
  id: string;
  residentId: string;
  date: ISODate;
  meals: Meal[];
  reason: string;
  source: "app" | "whatsapp";
  /** Where lunch is had that day. Missing means the default, the institute (college or office). */
  lunchAt?: LunchSpot;
  createdAt: ISODateTime;
}
export interface Mess {
  menu: MenuDay[];
  plateCost: Record<Meal, number>;
  rebatePerDay: number;
  rebateMinDays: number;
  cutoffs: Record<Meal, string>;
  servingTimes: Record<Meal, string>;
  specials: { date: ISODate; en: string; ml: string }[];
  optOuts: MealOptOut[];
}

export interface Notice {
  id: string;
  category: "maintenance" | "fees" | "safety" | "mess" | "general";
  pinned: boolean;
  audience: "all" | BlockId;
  postedAt: ISODateTime;
  title: string;
  titleMl: string;
  body: string;
  bodyMl: string;
}

export type ActivityKind =
  | "payment"
  | "gate_in"
  | "gate_out"
  | "complaint"
  | "complaint_resolved"
  | "optout"
  | "visitor"
  | "leave_request"
  | "leave_approved"
  | "leave_rejected"
  | "checkin"
  | "invoices_raised"
  | "reminders_sent"
  | "bed_moved";
export interface Activity {
  id: string;
  at: ISODateTime;
  kind: ActivityKind;
  residentId?: string;
  amount?: number;
  method?: string | null;
  invoiceId?: string;
  complaintId?: string;
  channel?: Channel;
  meals?: Meal[];
  visitorName?: string;
  leaveId?: string;
  count?: number;
  month?: string;
  fromBed?: string;
  toBed?: string;
}

export type WATemplate =
  | "invoice"
  | "reminder_due"
  | "reminder_overdue"
  | "receipt"
  | "complaint_ack"
  | "complaint_update"
  | "complaint_resolved"
  | "leave_request"
  | "leave_decision"
  | "gate_in"
  | "gate_out"
  | "late_entry"
  | "weekly_summary"
  | "optout_ack"
  | "welcome";
export interface WAMessage {
  id: string;
  from: "hostel" | "contact";
  at: ISODateTime;
  kind: "text" | "template" | "image";
  text?: string;
  template?: WATemplate;
  data?: Record<string, string | number>;
  image?: string;
  status?: "sent" | "delivered" | "read";
  /** set when a quick-reply button on this message has been used */
  answered?: string;
}
export interface WAThread {
  id: string;
  contactName: string;
  role: "resident" | "parent";
  residentId: string;
  phone: string;
  unread: number;
  messages: WAMessage[];
}
